        c.SetLogFile(address(this));
        c.Initialized();

        c.Deposit{value: depositAmount}();

        uint256 balanceBefore = c.balances(address(this));
        uint256 contractBalanceBefore = address(c).balance;

        bool collectOk;
        try c.Collect(collectAmount) {
            collectOk = true;
        } catch {
            collectOk = false;
        }

