        uint256 contractBalanceAfter = address(c).balance;

        if (collectOk) {
            assert(balanceBefore >= collectAmount && balanceAfter == balanceBefore - collectAmount && contractBalanceBefore >= collectAmount && contractBalanceAfter == contractBalanceBefore - collectAmount);
        } else {
            assert(balanceAfter == balanceBefore && contractBalanceAfter == contractBalanceBefore);
        }
    }

