            reverted ?
                (afterRecorded == beforeRecorded && afterContractBalance == beforeContractBalance && afterThisBalance == beforeThisBalance) :
                (beforeRecorded >= collectAmount && beforeContractBalance >= collectAmount && afterRecorded == beforeRecorded - collectAmount && afterContractBalance == beforeContractBalance - collectAmount && afterThisBalance == beforeThisBalance + collectAmount)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint d) public payable {
        require(address(this).balance >= d);

        c.Deposit{value: d}();

        uint recordedAfterDeposit = c.balances(address(this));
        uint thisBalanceAfterDeposit = address(this).balance;
        uint contractBalanceAfterDeposit = address(c).balance;

        try c.Collect(d) {
            // first collect succeeded
        } catch {
            revert();
        }

        uint recordedAfterFirstCollect = c.balances(address(this));
        uint thisBalanceAfterFirstCollect = address(this).balance;
        uint contractBalanceAfterFirstCollect = address(c).balance;

        bool secondReverted;
        try c.Collect(d) {
